--- src/db/scoped.js
     1	const db = require('./pool');
     2	
     3	function scoped(tenantId) {
     4	  if (!tenantId) throw new Error('scoped() needs a tenant id');
     5	  const where = (filters) => {
     6	    const keys = Object.keys(filters);
     7	    const clause = ['tenant_id = $1', ...keys.map((k, i) => k + ' = $' + (i + 2))].join(' AND ');
     8	    return { clause, params: [tenantId, ...keys.map((k) => filters[k])] };
     9	  };
    10	  return {
    11	    select(table, filters = {}) {
    12	      const w = where(filters);
    13	      return db.query('SELECT * FROM ' + table + ' WHERE ' + w.clause, w.params);
    14	    },
    15	    insert(table, row) {
    16	      const cols = ['tenant_id', ...Object.keys(row)];
    17	      const params = [tenantId, ...Object.values(row)];
    18	      return db.query('INSERT INTO ' + table + ' (' + cols.join(', ') + ') VALUES (' + params.map((_, i) => '$' + (i + 1)).join(', ') + ')', params);
    19	    },
    20	    remove(table, filters) {
    21	      const w = where(filters);
    22	      return db.query('DELETE FROM ' + table + ' WHERE ' + w.clause, w.params);
    23	    },
    24	  };
    25	}
    26	
    27	module.exports = { scoped };

